import{at as e,it as t,t as n,yt as r}from"./chunks/framework.CqXnyklt.js";var i=JSON.parse(`{"title":"Using Ember and React on the Same Page","description":"Import @warp-drive/alien-signals/install before the Ember and React install entry points so one WarpDrive store re-renders both Ember and React components on the same page.","frontmatter":{"description":"Import @warp-drive/alien-signals/install before the Ember and React install entry points so one WarpDrive store re-renders both Ember and React components on the same page."},"headers":[],"relativePath":"guides/the-manual/cookbook/multiple-frameworks-on-one-page.md","filePath":"guides/the-manual/cookbook/multiple-frameworks-on-one-page.md"}`),a={name:`guides/the-manual/cookbook/multiple-frameworks-on-one-page.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="using-ember-and-react-on-the-same-page" tabindex="-1">Using Ember and React on the Same Page <a class="header-anchor" href="#using-ember-and-react-on-the-same-page" aria-label="Permalink to “Using Ember and React on the Same Page”">​</a></h1><h2 id="in-this-guide" tabindex="-1">In This Guide <a class="header-anchor" href="#in-this-guide" aria-label="Permalink to “In This Guide”">​</a></h2><p><strong><em>Warp</em>Drive</strong> doesn&#39;t wrap your data in any one framework&#39;s signals. Instead, it calls a set of <a href="/pr-preview/pr-11402/api/@warp-drive/core/configure/types/SignalHooks">SignalHooks</a> whenever data is read or changes, and each framework&#39;s <code>install</code> entry point provides the hooks for that framework. Ember only re-renders for Ember&#39;s tags, and React only re-renders for the signals its watchers subscribe to. So when both frameworks render the same data, both need to hear about every read and every change.</p><p><a href="/pr-preview/pr-11402/api/@warp-drive/alien-signals/"><code>@warp-drive/alien-signals</code></a> does this for you. Its <code>install</code> entry point configures a signals graph that other frameworks add their signals to, instead of replacing it. This guide installs it alongside Ember and React, so that one store re-renders components in both frameworks.</p><ul><li><a href="#before-you-start">Before You Start</a></li><li><a href="#install-the-signals">Install the Signals</a></li><li><a href="#how-the-frameworks-share-signals">How the Frameworks Share Signals</a></li><li><a href="#share-the-store">Share the Store</a></li><li><a href="#other-frameworks">Other Frameworks</a></li></ul><h2 id="before-you-start" tabindex="-1">Before You Start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to “Before You Start”">​</a></h2><p>This guide assumes an Ember app that also renders React components, with both <code>@warp-drive/ember</code> and <code>@warp-drive/react</code> installed as described in <a href="/pr-preview/pr-11402/guides/installation/">Installation</a>. You don&#39;t need <a href="/pr-preview/pr-11402/guides/the-manual/schemas/resources/polaris-mode">PolarisMode</a> for this; see <a href="/pr-preview/pr-11402/guides/faq/polaris-mode-with-ember-and-react">Do I need PolarisMode to share state between Ember and React on the same page?</a>.</p><p>Add <code>@warp-drive/alien-signals</code> to your app, pinned to the same version as your other <strong><em>Warp</em>Drive</strong> packages. <code>@warp-drive/react</code> already depends on it, but your app imports it directly, so it needs to be one of your app&#39;s own dependencies too.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @warp-drive/alien-signals</span></span></code></pre></div><h2 id="install-the-signals" tabindex="-1">Install the Signals <a class="header-anchor" href="#install-the-signals" aria-label="Permalink to “Install the Signals”">​</a></h2><p>Import <code>@warp-drive/alien-signals/install</code> at the top of your app&#39;s entry point and your test setup, before the Ember and React <code>install</code> imports:</p><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-55" id="tab-56" checked><label data-title="app/app.ts" for="tab-56">app/app.ts</label><input type="radio" name="group-55" id="tab-57"><label data-title="tests/test-helper.ts" for="tab-57">tests/test-helper.ts</label></div><div class="blocks"><div class="language-ts active"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/alien-signals/install&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/ember/install&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/react/install&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/alien-signals/install&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/ember/install&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/react/install&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div></div></div><p>The order matters for Ember. On its own, <code>@warp-drive/ember/install</code> configures Ember&#39;s autotracking as <strong><em>Warp</em>Drive</strong>&#39;s only signals implementation. When <code>@warp-drive/alien-signals/install</code> has already run, Ember registers its tags with the alien-signals graph instead. Importing <code>@warp-drive/alien-signals/install</code> after <code>@warp-drive/ember/install</code> throws an error that says so.</p><p><code>@warp-drive/react/install</code> imports <code>@warp-drive/alien-signals/install</code> itself, so React works in either position. Listing alien-signals first anyway keeps the rule simple: it always comes first.</p><div class="tip custom-block"><p class="custom-block-title">Already composing signal hooks yourself?</p><p>If your app combines each framework&#39;s <code>buildSignalConfig</code> in its own <code>setupSignals</code> call, so that <code>createSignal</code> returns one signal per framework, you no longer need it. Delete that call, and replace the import of the module it lives in with the three imports above.</p></div><h2 id="how-the-frameworks-share-signals" tabindex="-1">How the Frameworks Share Signals <a class="header-anchor" href="#how-the-frameworks-share-signals" aria-label="Permalink to “How the Frameworks Share Signals”">​</a></h2><p>You don&#39;t need any of this to use the setup above, but it explains why it works.</p><ul><li><strong>Signals.</strong> Each time <strong><em>Warp</em>Drive</strong> creates a signal, the alien-signals graph creates an Ember tag to go with it. Reading or changing the data consumes or dirties both, so Ember&#39;s autotracking and the graph each see every read and change.</li><li><strong>React.</strong> React&#39;s integration watches the graph directly. A signal read while a component renders inside a <a href="/pr-preview/pr-11402/api/@warp-drive/react/functions/ReactiveContext"><code>ReactiveContext</code></a> is added to that context&#39;s watcher.</li><li><strong>Memos.</strong> Values <strong><em>Warp</em>Drive</strong> memoizes, such as <a href="/pr-preview/pr-11402/guides/the-manual/schemas/derivations">derived fields</a> and some request and pagination state, are memos in the alien-signals graph; neither framework creates its own. A React component watches the memo itself, so it re-renders whenever anything the memo depends on changes. Ember sees each memo as one more tag: reading the memo consumes it, whether the memo runs or returns a cached value, and the graph dirties it as soon as anything the memo depends on changes. Memoized values update in both frameworks, whichever one read them first.</li><li><strong>Test waiters.</strong> Each framework&#39;s <code>waitFor</code> hook still runs, so <code>await settled()</code> from <code>@ember/test-helpers</code> waits for <strong><em>Warp</em>Drive</strong>&#39;s requests in your Ember tests.</li></ul><p>Two behaviors differ from an Ember app that only imports <code>@warp-drive/ember/install</code>:</p><ul><li>A memo only recomputes when a signal managed by <strong><em>Warp</em>Drive</strong> changes. If a <a href="/pr-preview/pr-11402/guides/the-manual/schemas/derivations">derived field</a> reads state that only a framework tracks, such as an Ember <code>@tracked</code> property or a React <code>useState</code> value, the memo keeps returning its cached value when that state changes. Keep the state a derivation reads in <strong><em>Warp</em>Drive</strong>, for instance as a field on the resource it derives from.</li><li>With the <code>DEPRECATE_COMPUTED_CHAINS</code> deprecation active, a classic computed property that depends on a memoized key may not recompute when that memo changes.</li></ul><h2 id="share-the-store" tabindex="-1">Share the Store <a class="header-anchor" href="#share-the-store" aria-label="Permalink to “Share the Store”">​</a></h2><p>Both frameworks need to render from the same store instance, not two stores built from the same class. Create it the usual way for Ember, then hand that instance to React&#39;s <a href="/pr-preview/pr-11402/api/@warp-drive/react/functions/StoreProvider"><code>StoreProvider</code></a> with its <code>store</code> prop, as <a href="/pr-preview/pr-11402/guides/configuration/react">Setup - React</a> describes.</p><div class="language-tsx"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">StoreProvider</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> store</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{store}&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">UserList</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">StoreProvider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h2 id="other-frameworks" tabindex="-1">Other Frameworks <a class="header-anchor" href="#other-frameworks" aria-label="Permalink to “Other Frameworks”">​</a></h2><p>The same setup works for other frameworks: import <code>@warp-drive/alien-signals/install</code> first, then each framework&#39;s <code>install</code> entry point. An <code>install</code> entry point that calls <a href="/pr-preview/pr-11402/api/@warp-drive/core/configure/functions/registerSignals"><code>registerSignals</code></a>, as <code>@warp-drive/ember/install</code> and <code>@warp-drive/tc39-proposal-signals/install</code> do, registers with the graph when alien-signals is installed, and configures that framework on its own when it isn&#39;t.</p><p>To add a framework that doesn&#39;t have a <strong><em>Warp</em>Drive</strong> package yet, pass its hooks to <a href="/pr-preview/pr-11402/api/@warp-drive/alien-signals/install/functions/registerSignalIntegration"><code>registerSignalIntegration</code></a>. <a href="/pr-preview/pr-11402/api/@warp-drive/alien-signals/install/types/SignalIntegration">SignalIntegration</a> describes the two shapes an integration can take: one that brings its own signals, like Ember, and one that observes the graph&#39;s signals and memos, like React.</p>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};